// row-major traversal (cache-friendly)
for (i = 0; i < N; i++) for (j = 0; j < N; j++) sum += a[i][j];
// column-major traversal of row-major array (cache-hostile): ~10× slower for large N
for (j = 0; j < N; j++) for (i = 0; i < N; i++) sum += a[i][j];

// Array of structs: scanning 'price' loads unused fields too
struct Item { char name[48]; double price; int qty; } items[N];
for (i = 0; i < N; i++) total += items[i].price;   // 1 useful double per ~64 B line
// Struct of arrays: 8 prices per cache line
double price[N];
for (i = 0; i < N; i++) total += price[i];

// bad: counters share cache lines
long counters[NTHREADS];
// good: each counter on its own line
struct alignas(64) padded { long v; };
struct padded counters2[NTHREADS];
